hand = '2C 3D 7H 5H 2S'

    def score_hand(hand):
        """Return a tuple that ranks a hand; higher tuples are better."""
        cards = hand.split()
        ranks = sorted((_RANKS[card[:-1]] for card in cards), reverse=True)
        is_flush = len({card[-1] for card in cards}) == 1

        counts = {}
        for rank in ranks:
            counts[rank] = counts.get(rank, 0) + 1

        is_wheel = ranks == [14, 5, 4, 3, 2]  # ace-low straight
        is_straight = len(set(ranks)) == 5 and (ranks[0] - ranks[4] == 4 or is_wheel)
        # The ace-low straight (A-2-3-4-5) scores as a 5-high straight.
        straight_high = 5 if is_wheel else (ranks[0] if is_straight else 0)

        if is_straight and is_flush:
            return (_STRAIGHT_FLUSH, straight_high)
        if 4 in counts.values():
            quad = next(r for r, c in counts.items() if c == 4)
            kicker = next(r for r, c in counts.items() if c == 1)
            return (_FOUR_KIND, quad, kicker)
        if is_flush:
            return (_FLUSH, *ranks)
        if 3 in counts.values() and 2 in counts.values():
            trip = next(r for r, c in counts.items() if c == 3)
            pair = next(r for r, c in counts.items() if c == 2)
