            kickers = sorted((r for r, c in counts.items() if c == 1), reverse=True)
            return (_THREE_KIND, trip, *kickers)
        if len(counts) == 4 and 2 in counts.values():
            pairs = sorted((r for r, c in counts.items() if c == 2), reverse=True)
